="rgb(255,0,0)" stroke="none" font-family="geogebra-sans-serif, sans-serif" font-size="16px" font-style="normal" font-weight="normal" text-decoration="normal" x="123" y="69" text-anchor="start" dominant-baseline="alphabetic" fill-opacity="1">R</text></g></g>
